        if(['path','water'].includes(sculptTool)&&state.paths.length>=64){caption('This study supports 64 landscape strokes.');return;}
        brushStroke={before:snapshot(),controller,owner,last:null,path:null};
        if(['path','water'].includes(sculptTool)){brushStroke.path={id:crypto.randomUUID(),kind:sculptTool,points:[]};state.paths.push(brushStroke.path);}
