    function xrCommand(id,source){
        actionSource=source;
        try{
            if(id==='guide-close'){guidePanel.mesh.visible=false;guideEpoch++;guideVoice?.cancel();cues.play('tap',source);return;}if(id==='guide-next'){guideCaptionText='';guideVoice?.cancel();guidePage=(guidePage+1)%Math.max(1,guidePages.length);renderGuideCard();cues.play('tap',source);return;}if(id==='guide-replay'){if(cues.enabled)void guideVoice?.speak(guidePages[guidePage]);cues.play('tap',source);return;}
            if(id.startsWith('v4:')){cues.play('tap',source);void v4.command(id.slice(3)).catch(error=>caption(error.message));return;}
            if(id.startsWith('v3:')){cues.play('tap',source);void v3.command(id.slice(3)).catch(error=>caption(error.message));return;}
            if(id==='goal'){const goals=['diverse','fruit-focus','lower-input'];commit(()=>state.goal=goals[(goals.indexOf(state.goal)+1)%3]);}
            else if(id.startsWith('page:')){xrPage=id.slice(5);setTab(xrPage==='inspect'?'discover':xrPage);}
            else if(id.startsWith('layer:')){layerId=id.slice(6);variant=0;updateBay();renderPanel();}
            else if(id.startsWith('variant:')){variant=+id.slice(8);renderPanel();}
            else if(id.startsWith('plant:')){selectedPlant=database.records.find(record=>record.id===id.slice(6));if(layers.some(layer=>layer.id===selectedPlant.layer?.value))layerId=selectedPlant.layer.value;variant=0;updateBay();xrPage='pieces';renderPanel();cues.play('grow',source);}
            else if(id.startsWith('collection:'))xrCollectionPage+=id.endsWith('next')?1:-1;
            else if(id==='exit')void session?.end();
            else if(id==='recenter')pendingXRRecenter=true;
            else if(id.startsWith('scale:'))world.scale.setScalar(THREE.MathUtils.clamp(world.scale.x*(id.endsWith('plus')?1.15:1/1.15),.14,.34));
            else if(id.startsWith('canopy:')){const item=state.pieces.find(p=>p.id===selected);if(item)commit(()=>{item.canopyDiameterM=THREE.MathUtils.clamp((item.canopyDiameterM||0)+(id.endsWith('plus')?.5:-.5),0,60);item.footprintBasis='user-design-assumption';});}
            else if(id.startsWith('width:')||id.startsWith('depth:')){const field=id.startsWith('width')?'widthM':'depthM';commit(()=>state[field]=THREE.MathUtils.clamp(state[field]+(id.endsWith('plus')?2:-2),2,1000));}
            else if(id.startsWith('shape:')){commit(()=>{state.shape=id.slice(6);state.boundary=foodForestBoundary(state.shape);});paintBoard();}
            else if(id.startsWith('challenge:')){challenge=challenge===id.slice(10)?'':id.slice(10);if(tab==='board')renderPanel();}
            else{if(!root.querySelector(`[data-action="${id}"]`))setTab('board');root.querySelector(`[data-action="${id}"]`)?.click();return;}
            cues.play('tap',source);
        }finally{actionSource=null;renderXRPanel();}
    }
    function controllerRay(controller){scene.updateMatrixWorld(true);raycaster.ray.origin.setFromMatrixPosition(controller.matrixWorld);raycaster.ray.direction.set(0,0,-1).transformDirection(controller.matrixWorld);}
    function panelHit(){for(const hit of raycaster.intersectObjects([xrPanel.mesh,guidePanel.mesh])){const control=(hit.object===guidePanel.mesh?guidePanel:xrPanel).hit(hit);if(control)return control;}return null;}
    function endXRGrab(controller,cancel=false,owner){
        if(brushStroke?.controller===controller){if(cancel||!owner||brushStroke.owner===owner)finishSculpt(cancel);return;}
        const grab=xrGestures.get(controller);if(!grab||owner&&grab.owner!==owner)return;xrGestures.delete(controller);
        const item=state.pieces.find(piece=>piece.id===grab.id);
        if(cancel||!item||!boardPointInside(item,state.boundary)){state=grab.before;selected='';update();if(!cancel)cues.play('error',controller.userData.source);}
        else{remember(grab.before);cues.play(grab.isNew?'grow':'place',controller.userData.source);}
    }
    function startXRGrab(controller,allowPanel,owner){
        if(!session||!controller.visible||xrGestures.size||brushStroke)return;controllerRay(controller);
        const control=allowPanel&&panelHit();if(control){xrCommand(control.id,controller.userData.source);return;}
        const point=rayPoint();
        if(walkMode){const hit=hitPiece();if(hit?.userData.instanceId){selected=hit.userData.instanceId;v3.mark('inspect');save();xrPage='discover';update();}else if(point&&boardPointInside(point,state.boundary)){const p=new THREE.Vector3(point.x,forestSurfaceY(state,point.x,point.z),point.z).applyMatrix4(world.matrixWorld),viewer=renderer.xr.getCamera().getWorldPosition(new THREE.Vector3());world.position.x+=viewer.x-p.x;world.position.z+=viewer.z-p.z;cues.play('place',controller.userData.source);}return;}
        if(!point)return;
        if(sculptTool!=='select'){if(allowPanel)beginSculpt(point,controller,owner);return;}
        if(drawing){if(Math.abs(point.x)<3&&Math.abs(point.z)<2){drawing.push(point);drawBoundaryPreview();renderXRPanel();cues.play('place',controller.userData.source);}return;}
        const hit=hitPiece();if(!hit)return;const before=snapshot();let item,isNew=false;
        if(hit.userData.bayVariant!==undefined){if(state.pieces.length>=160)return;isNew=true;item={id:crypto.randomUUID(),layer:layerId,variant:hit.userData.bayVariant,x:point.x,z:point.z,size:1,plantId:selectedPlant?.id||'',label:selectedPlant?.commonName||''};state.pieces.push(item);}
        else item=state.pieces.find(piece=>piece.id===hit.userData.instanceId);
        selected=item.id;xrGestures.set(controller,{id:item.id,before,isNew,owner,offset:{x:isNew?0:point.x-item.x,z:isNew?0:point.z-item.z}});syncTokens();cues.play('grab',controller.userData.source);renderXRPanel();
    }
    for(let i=0;i<2;i++){
        const controller=renderer.xr.getController(i);scene.add(controller);xrControllers.push(controller);
        const beam=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(),new THREE.Vector3(0,0,-1)]),new THREE.LineBasicMaterial({color:0x759582}));beam.scale.z=3;controller.add(beam);
        controller.addEventListener('connected',event=>{controller.userData.source=event.data;xrLatch.reset();});
        controller.addEventListener('disconnected',()=>{endXRGrab(controller,true);controller.userData.source=null;xrLatch.reset();});
        controller.addEventListener('selectstart',()=>startXRGrab(controller,true,'select'));controller.addEventListener('selectend',()=>endXRGrab(controller,false,'select'));
        controller.addEventListener('squeezestart',()=>startXRGrab(controller,false,'squeeze'));controller.addEventListener('squeezeend',()=>endXRGrab(controller,false,'squeeze'));
    }
    function tickXR(frame){
        if(!session||!frame||session.visibilityState==='hidden')return;
        if(pendingXRRecenter){const pose=frame.getViewerPose(renderer.xr.getReferenceSpace());if(pose){const p=pose.transform.position,q=pose.transform.orientation,f=new THREE.Vector3(0,0,-1).applyQuaternion(new THREE.Quaternion(q.x,q.y,q.z,q.w));f.y=0;f.normalize();world.position.set(p.x+f.x*1.15,p.y-.55,p.z+f.z*1.15);world.rotation.set(0,Math.atan2(-f.x,-f.z),0);world.scale.setScalar(.22);if(walkMode){world.scale.set(state.widthM/6,state.widthM/6,state.depthM/4);world.position.set(p.x,-.16*state.widthM/6,p.z);anchorWalkPanel(p,q);}pendingXRRecenter=false;}}
        let focus='';
        for(const controller of xrControllers){const source=controller.userData.source;
            if(source&&xrLatch.poll(source,source.gamepad?.buttons[3]?.pressed)){xrPanel.mesh.visible=!xrPanel.mesh.visible;if(walkMode&&xrPanel.mesh.visible){const viewer=renderer.xr.getCamera();anchorWalkPanel(viewer.getWorldPosition(new THREE.Vector3()),viewer.getWorldQuaternion(new THREE.Quaternion()));}cues.play('tap',source);}
            if(!controller.visible){endXRGrab(controller,true);continue;}
            controllerRay(controller);if(brushStroke?.controller===controller){const point=rayPoint();if(point)stepSculpt(point);continue;}const grab=xrGestures.get(controller);
            if(grab){const point=rayPoint(),item=state.pieces.find(piece=>piece.id===grab.id);if(point&&item){movePlant(item,point.x-grab.offset.x,point.z-grab.offset.z);objects.get(item.id).group.position.set(item.x,forestSurfaceY(state,item.x,item.z)+.16,item.z);}}
            else focus ||= panelHit()?.id||'';
        }
        xrPanel.hover(focus);
    }
    async function enterXR(){
        if(disposed||session||xrPending||!xrSupport)return;xrPending=true;xrButton.disabled=true;
        try{
            const next=await navigator.xr.requestSession(xrSupport,{optionalFeatures:['local-floor','hand-tracking']});
            if(disposed){await next.end();return;}cancelDrag();session=next;root.classList.add('is-xr');xrPanel.mesh.visible=true;pendingXRRecenter=true;xrLatch.reset();
            next.addEventListener('visibilitychange',()=>{if(next.visibilityState!=='visible')for(const controller of xrControllers)endXRGrab(controller,true);});
            next.addEventListener('end',()=>{for(const controller of xrControllers)endXRGrab(controller,true);session=null;if(walkMode)setWalk(false);xrPanel.mesh.visible=false;world.position.set(0,0,0);world.scale.setScalar(1);root.classList.remove('is-xr');fit();xrLatch.reset();xrButton.disabled=disposed;});
            await renderer.xr.setSession(next);renderXRPanel();cues.play('grow');
        }catch(error){if(session){try{await session.end();}catch{/* Already ended. */}}caption(`XR could not start: ${error.message}`);}
        finally{xrPending=false;xrButton.disabled=disposed||!!session||!xrSupport;}
    }
    if(navigator.xr){void(async()=>{try{xrSupport=await navigator.xr.isSessionSupported('immersive-ar')?'immersive-ar':await navigator.xr.isSessionSupported('immersive-vr')?'immersive-vr':'';}catch{/* Desktop preview still works. */}if(!disposed){xrButton.disabled=!xrSupport;xrButton.title=xrButton.ariaLabel=xrSupport?'Enter XR table':'XR unavailable on this browser';}})();}
    renderer.domElement.addEventListener('pointerdown',event=>{if(session||event.button!==0)return;const point=ray(event);const control=panelHit();if(control){xrCommand(control.id);return;}renderer.domElement.setPointerCapture(event.pointerId);if(walkMode){const hit=hitPiece();if(hit?.userData.instanceId){selected=hit.userData.instanceId;v3.mark('inspect');save();setTab('discover');update();}else drag={type:'look',x:event.clientX,y:event.clientY,yaw:camera.rotation.y,pitch:camera.rotation.x};return;}if(!point)return;if(sculptTool!=='select'){beginSculpt(point);return;}if(drawing){if(Math.abs(point.x)<3&&Math.abs(point.z)<2){drawing.push(point);caption(`${drawing.length} boundary corners. Choose Use boundary when ready.`);drawBoundaryPreview();}return;}const hit=hitPiece();if(hit?.userData.bayVariant!==undefined){if(state.pieces.length>=160)return;const before=snapshot(),id=crypto.randomUUID();state.pieces.push({id,layer:layerId,variant:hit.userData.bayVariant,x:point.x,z:point.z,size:1,plantId:selectedPlant?.id||'',label:selectedPlant?.commonName||''});selected=id;syncTokens();drag={type:'piece',id,before,isNew:true,offset:{x:0,z:0}};cues.play('grab');}
        else if(hit?.userData.instanceId){selected=hit.userData.instanceId;v3.mark('inspect');const item=state.pieces.find(p=>p.id===selected);drag={type:'piece',id:selected,before:snapshot(),offset:{x:point.x-item.x,z:point.z-item.z}};syncTokens();cues.play('grab');}
        else drag={type:'orbit',x:event.clientX,before:world.rotation.y};}, {signal});
    renderer.domElement.addEventListener('pointermove',event=>{if(brushStroke){const point=ray(event);if(point)stepSculpt(point);return;}if(!drag)return;const point=ray(event);if(drag.type==='look'){camera.rotation.order='YXZ';camera.rotation.y=drag.yaw-(event.clientX-drag.x)*.004;camera.rotation.x=THREE.MathUtils.clamp(drag.pitch-(event.clientY-drag.y)*.004,-1.2,1.2);return;}if(drag.type==='orbit'){world.rotation.y=drag.before+(event.clientX-drag.x)*.005;return;}if(!point)return;const item=state.pieces.find(p=>p.id===drag.id);movePlant(item,point.x-drag.offset.x,point.z-drag.offset.z);objects.get(item.id)?.group.position.set(item.x,forestSurfaceY(state,item.x,item.z)+.14,item.z);caption(boardPointInside(item,state.boundary)?'Release to place.':'Outside the planting area · move back onto the board.');},{signal});
    renderer.domElement.addEventListener('pointerup',()=>{if(brushStroke){finishSculpt();return;}if(!drag)return;const active=drag;drag=null;if(active.type==='piece'){const item=state.pieces.find(p=>p.id===active.id);if(!item||!boardPointInside(item,state.boundary)){state=active.before;selected='';update();caption('Placement cancelled. The piece stayed in the loading bay.');cues.play('error');}else{remember(active.before);cues.play(active.isNew?'grow':'place');caption('Placed. Saved on this device.');}}},{signal});
    function cancelDrag(){if(brushStroke)finishSculpt(true);if(drag?.type==='piece'){state=drag.before;selected='';update();}drag=null;}
    renderer.domElement.addEventListener('pointercancel',cancelDrag,{signal});window.addEventListener('blur',cancelDrag,{signal});
